interactions.query:
query Doctor($owner0: String!, $name0: String!, $owner1: String!, $name1: String!, $owner2: String!, $name2: String!) {
  viewer { login }
  repo0: repository(owner: $owner0, name: $name0) { nameWithOwner hasIssuesEnabled }
  repo1: repository(owner: $owner1, name: $name1) { nameWithOwner hasIssuesEnabled }
  repo2: repository(owner: $owner2, name: $name2) { nameWithOwner hasIssuesEnabled }
}
